package io.github.jesterportfolio.hearth.survival.rpg;

import java.util.*;import java.util.concurrent.*;import java.util.function.*;
import org.bukkit.*;import org.bukkit.entity.*;import org.bukkit.event.*;import org.bukkit.event.entity.*;import org.bukkit.event.player.*;import org.bukkit.plugin.java.JavaPlugin;import org.bukkit.persistence.PersistentDataType;import org.bukkit.inventory.ItemStack;import org.bukkit.potion.*;
import net.kyori.adventure.text.Component;
import io.github.jesterportfolio.hearth.survival.*;import io.github.jesterportfolio.hearth.survival.housing.*;import io.github.jesterportfolio.hearth.economy.RpgStore;import io.github.jesterportfolio.hearth.survival.skills.WorldAccessPolicy.Role;

/** 경제 RPG의 남은 정책/보상/장비/UI를 한 실행 수명주기로 통합한다. */
public final class RpgRuntime implements Listener,AutoCloseable {
    public final JavaPlugin plugin;public final SurvivalRuntime runtime;public final RpgAura aura;public final RpgPolicy policy;public final RpgStore store;public final Properties config;public final Executor owner;
    public final ExtraWorlds extras;public final RpgDeath death;public final RpgObjects objects;public final RpgRewards rewards;public final RpgMenu menu;public final RpgHud hud;public final io.github.jesterportfolio.hearth.survival.enchants.EnchantRuntime enchants;
    public final io.github.jesterportfolio.hearth.survival.platform.PlatformRuntime platform;
    private RpgStore.Snapshot snapshot=new RpgStore.Snapshot(List.of(),Map.of(),Map.of(),List.of());private boolean opened,held,closed,changing;private long generation;
    public long generation(){return generation;}
    private final org.bukkit.scheduler.BukkitTask pulse;private final Map<UUID,Map<PotionEffectType,PotionEffect>> effects=new HashMap<>();
    public RpgRuntime(JavaPlugin plugin,SurvivalRuntime runtime,RpgAura aura,UUID group)throws Exception{
        this.plugin=plugin;this.runtime=runtime;this.aura=aura;policy=aura.policy;config=RpgAura.read(plugin,"economy-rpg.content-file","rpg-content.properties");owner=runtime.economy().owner;var at=runtime.worlds().entry(SurvivalWorld.RESIDENCE);store=new RpgStore(runtime.economy().database(),runtime.economy().store,runtime.economy().settings.realm(),at.getWorld().getUID(),at.getBlockX(),at.getBlockY(),at.getBlockZ(),runtime.housing().settings);
        extras=new ExtraWorlds(plugin,runtime.worlds(),store,config,group,runtime.economy().settings.realm(),owner);death=new RpgDeath(this,group);objects=new RpgObjects(this);rewards=new RpgRewards(this);menu=new RpgMenu(this);hud=new RpgHud(this);runtime.housing().protection.pvpPolicy(id->snapshot.pvp().getOrDefault(id,new RpgStore.Pvp(id,false,0)).enabled());runtime.housing().interactionPolicy(objects::allowed);enchants=plugin.getConfig().getBoolean("hearth-enchants.enabled")?new io.github.jesterportfolio.hearth.survival.enchants.EnchantRuntime(this):null;platform=plugin.getConfig().getBoolean("hearth-platform.enabled")?new io.github.jesterportfolio.hearth.survival.platform.PlatformRuntime(this):null;runtime.housing().pvpPolicy((source,target)->ready()&&pvp(target.getWorld())&&source.getWorld()==target.getWorld()&&runtime.admission().decision(source.getUniqueId(),source.getLocation()).allowed()&&runtime.admission().decision(target.getUniqueId(),target.getLocation()).allowed());
        Bukkit.getPluginManager().registerEvents(this,plugin);pulse=Bukkit.getScheduler().runTaskTimer(plugin,()->{if(!ready())return;try{if(!aura.valid())throw new IllegalStateException("RPG_CONTENT_UNAVAILABLE");for(var p:Bukkit.getOnlinePlayers()){if(death.journal.held(p.getUniqueId())){p.kick(Component.text("사망 결과 보류 · 관리자 확인이 필요합니다."));continue;}boolean allowed=abilityAllowed(p);aura.reconcile(p,allowed);if(!allowed)clearEffects(p);}rewards.expire();hud.publish();}catch(Exception error){hold(error);}},10,10);
        for(String command:List.of("hearthskills","hearthrpg","home","sethome","objectaccess","hearthskill"))Objects.requireNonNull(plugin.getCommand(command)).setExecutor((sender,c,label,args)->{if(!(sender instanceof Player p))return true;if(!available(p)){p.sendMessage(Component.text("접속·거래·정책 준비가 끝난 뒤 이용하세요."));return true;}try{switch(command){case "hearthskills"->menu.skills(p);case "hearthrpg"->menu.main(p);case "objectaccess"->objects.command(p,args);case "sethome"->setHome(p);case "home"->home(p);case "hearthskill"->{if(args.length==1)activate(p,args[0]);else menu.skills(p);}default->throw new IllegalStateException();}}catch(Exception error){p.sendMessage(Component.text("현재 조건 또는 안전한 위치를 확인해 주세요."));}return true;});
    }
    public CompletionStage<Void> open(){return aura.ready().thenCompose(v->store.snapshot()).thenComposeAsync(s->{snapshot=s;return extras.open(s);},owner).thenComposeAsync(v->refresh(),owner).thenComposeAsync(v->project(),owner).thenComposeAsync(v->enchants==null?CompletableFuture.completedFuture(null):enchants.open(),owner).thenRunAsync(()->{opened=true;plugin.getLogger().info("HEARTH_RPG_READY worlds="+runtime.worlds().worlds().size());},owner).thenComposeAsync(v->platform==null?new io.github.jesterportfolio.hearth.economy.PlatformStore(runtime.economy().database(),runtime.economy().store,runtime.economy().settings.realm()).requireInactive():platform.open(),owner).whenCompleteAsync((v,e)->{if(e!=null)hold(e);},owner);}
    public boolean ready(){return opened&&!held&&!closed;}
    public boolean available(Player p){return ready()&&runtime.economy().free(p)&&runtime.current(p)&&!p.isDead()&&!changing&&aura.loaded(p.getUniqueId());}
    public Role role(World w){return runtime.admission().role(w);}
    public boolean roleReady(World w){Role role=role(w);return ready()&&role!=null&&(role.residence()||policy.ready(role));}
    public void hold(Throwable error){if(closed)return;held=true;plugin.getLogger().log(java.util.logging.Level.SEVERE,"HEARTH_RPG_HOLD",error);runtime.systemHold("경제 RPG 처리 보류 · 원본과 표식을 확인해 주세요.");}
    public RpgStore.Snapshot snapshot(){return snapshot;}
    public CompletionStage<Void> refresh(){return store.snapshot().thenComposeAsync(s->{snapshot=s;return objects.apply(s.objects());},owner).thenComposeAsync(v->{generation++;return applyPvp();},owner);}
    public CompletionStage<Void> reprojectWorlds(){return refresh().thenComposeAsync(v->project(),owner);}
    private CompletionStage<Void> project(){var xp=new TreeSet<String>();var disabled=new TreeSet<String>();for(var w:runtime.worlds().worlds().values()){Role role=role(w);if(policy.xpBlocked().contains(role))xp.add(w.getName());if(policy.abilitiesBlocked().contains(role))disabled.add(w.getName());}for(var h:runtime.housing().snapshot().houses()){String name=h.key().replace(':','_');if(policy.xpBlocked().contains(Role.PRIVATE_HOME))xp.add(name);if(policy.abilitiesBlocked().contains(Role.PRIVATE_HOME))disabled.add(name);}return aura.project(xp,disabled);}
    public boolean penalized(Player p){return policy.penaltyWorlds().contains(role(p.getWorld()))&&aura.penalized(p.getUniqueId());}
    public boolean pvp(World w){Role role=role(w);if(role==null)return false;if(role==Role.PUBLIC_HOME||role==Role.NOVICE_RESOURCE)return false;if(role==Role.PRIVATE_HOME){var h=runtime.housing().house(w);return h.isPresent()&&snapshot.pvp().getOrDefault(h.get().id(),new RpgStore.Pvp(h.get().id(),false,0)).enabled();}return true;}
    private CompletionStage<Void> applyPvp(){var managers=new HashSet<com.sk89q.worldguard.protection.managers.RegionManager>();for(var role:List.of(SurvivalWorld.NOVICE,SurvivalWorld.END)){var world=runtime.worlds().worlds().get(role);if(world!=null)runtime.housing().protection.resource(world,runtime.worlds().entry(role));}for(var w:Bukkit.getWorlds()){if(role(w)==null)continue;boolean value=pvp(w);w.setPVP(value);var manager=HousingProtection.manager(w);managers.add(manager);var region=manager.getRegion("hearth_rpg_world_pvp");if(region!=null&&(!(region instanceof com.sk89q.worldguard.protection.regions.GlobalProtectedRegion)||region.getPriority()!=900))throw new IllegalStateException("RPG_PVP_REGION_CONFLICT");if(region==null){region=new com.sk89q.worldguard.protection.regions.GlobalProtectedRegion("hearth_rpg_world_pvp");region.setPriority(900);manager.addRegion(region);}region.setFlag(com.sk89q.worldguard.protection.flags.Flags.PVP,value?com.sk89q.worldguard.protection.flags.StateFlag.State.ALLOW:com.sk89q.worldguard.protection.flags.StateFlag.State.DENY);var inside=manager.getRegion("hearth_house_inside");if(inside!=null)inside.setFlag(com.sk89q.worldguard.protection.flags.Flags.PVP,value?com.sk89q.worldguard.protection.flags.StateFlag.State.ALLOW:com.sk89q.worldguard.protection.flags.StateFlag.State.DENY);}return runtime.economy().database().module("rpg_pvp_wg_save",c->{for(var manager:managers)manager.save();return null;});}
    @EventHandler(priority=EventPriority.LOWEST,ignoreCancelled=true) public void damage(EntityDamageByEntityEvent e){var source=e.getDamager() instanceof Projectile projectile?projectile.getShooter():e.getDamager() instanceof Tameable tame?tame.getOwner():e.getDamager() instanceof TNTPrimed tnt?tnt.getSource():e.getDamager();if(source instanceof Player p&&aura.loaded(p.getUniqueId()))aura.reconcile(p,abilityAllowed(p));if(e.getEntity() instanceof Player p&&aura.loaded(p.getUniqueId()))aura.reconcile(p,abilityAllowed(p));if(e.getEntity() instanceof Player&&source instanceof org.bukkit.OfflinePlayer&&!pvp(e.getEntity().getWorld()))e.setCancelled(true);}
    public void change(Player p,Supplier<CompletionStage<Void>> action){if(!available(p))return;Object token=runtime.sessionToken(p);changing=true;p.closeInventory();try{action.get().thenComposeAsync(v->refresh(),owner).whenCompleteAsync((v,e)->{changing=false;if(e!=null){String code=io.github.jesterportfolio.hearth.inventory.InventorySaveSession.code(e);if(Set.of("RPG_CAS","RPG_NOT_OWNER","RPG_OBJECT_BOUNDS").contains(code)){changing=true;refresh().whenCompleteAsync((fresh,refreshError)->{changing=false;if(refreshError!=null)hold(refreshError);else if(runtime.current(p,token))p.sendMessage(Component.text("권한 또는 설정이 바뀌었습니다. 다시 확인해 주세요."));},owner);}else hold(e);}else if(runtime.current(p,token))p.sendMessage(Component.text("설정을 저장했습니다."));},owner);}catch(Exception e){changing=false;hold(e);}}
    public void togglePvp(Player p){var house=runtime.housing().snapshot().owned(p.getUniqueId()).orElseThrow();var old=snapshot.pvp().get(house.id());change(p,()->store.pvp(runtime.economy().context(p),house.id(),old==null||!old.enabled(),old==null?-1:old.revision()));}
    public void setHome(Player p){var at=p.getLocation();if(!runtime.admission().decision(p.getUniqueId(),at).allowed()||!SurvivalWorlds.safe(at))throw new IllegalStateException();var old=snapshot.homes().get(p.getUniqueId());change(p,()->store.home(runtime.economy().context(p),new RpgStore.Home(p.getUniqueId(),at.getWorld().getUID(),at.getX(),at.getY(),at.getZ(),at.getYaw(),at.getPitch(),0),old==null?-1:old.revision()));}
    public void home(Player p){var home=Optional.ofNullable(snapshot.homes().get(p.getUniqueId())).orElseThrow();runtime.moveRpg(p,"Home",()->{CompletionStage<?> load=Bukkit.getWorld(home.world())!=null?CompletableFuture.completedFuture(null):runtime.housing().snapshot().houses().stream().filter(h->home.world().equals(h.world())).findFirst().map(h->runtime.housing().target(p.getUniqueId(),h.id())).orElseThrow();return load.thenComposeAsync(v->{var w=Objects.requireNonNull(Bukkit.getWorld(home.world()));var at=new Location(w,home.x(),home.y(),home.z(),home.yaw(),home.pitch());return w.getChunkAtAsync(at.getBlockX()>>4,at.getBlockZ()>>4,false).thenApplyAsync(chunk->{if(chunk==null||!SurvivalWorlds.safe(at))throw new IllegalStateException("HOME_UNSAFE");return at;},owner);},owner);});}
    public boolean isCharm(ItemStack item){return item.hasItemMeta()&&item.getItemMeta().getPersistentDataContainer().has(new NamespacedKey(plugin,"death_charm"),PersistentDataType.BYTE);}
    public ItemStack charm(){var item=new ItemStack(Material.PAPER);item.editMeta(meta->{meta.displayName(Component.text("호신부적"));meta.getPersistentDataContainer().set(new NamespacedKey(plugin,"death_charm"),PersistentDataType.BYTE,(byte)1);});return item;}
    public boolean abilityAllowed(Player p){var role=role(p.getWorld());return ready()&&!p.isDead()&&role!=null&&!policy.abilitiesBlocked().contains(role)&&runtime.admission().decision(p.getUniqueId(),p.getLocation()).allowed();}
    public void activate(Player p,String id){var c=Optional.ofNullable(aura.custom.get(id)).orElseThrow();var user=aura.api.getUser(p.getUniqueId());int level=user.getManaAbilityLevel(c.active());if(!abilityAllowed(p)||level<1||user.getMana()<c.active().getManaCost(level)){p.sendMessage(Component.text("숙련도·마나·월드 조건을 확인해 주세요."));return;}Object token=runtime.sessionToken(p);double mana=c.active().getManaCost(level);long now=System.currentTimeMillis(),until=now+Math.round(c.active().getCooldown(level)*1000);store.reserveSkill(runtime.economy().context(p),c.skill().getId().toString(),now,until).whenCompleteAsync((v,error)->{if(error!=null){if(!"RPG_CAS".equals(io.github.jesterportfolio.hearth.inventory.InventorySaveSession.code(error)))hold(error);else if(runtime.current(p,token))p.sendMessage(Component.text("아직 재사용 대기 중입니다."));return;}if(!runtime.current(p,token)||!available(p)||!abilityAllowed(p))return;var event=new dev.aurelium.auraskills.api.event.mana.ManaAbilityActivateEvent(p,user,c.active(),c.seconds()*20,mana);Bukkit.getPluginManager().callEvent(event);if(event.isCancelled()||!Double.isFinite(event.getManaUsed())||event.getManaUsed()<0||!user.consumeMana(event.getManaUsed()))return;if(c.effect().equals("HEAL"))p.setHealth(Math.min(p.getMaxHealth(),p.getHealth()+c.activeValue()));else{var type=switch(c.effect()){case "SPEED"->PotionEffectType.SPEED;case "HASTE"->PotionEffectType.HASTE;case "RESISTANCE"->PotionEffectType.RESISTANCE;default->throw new IllegalStateException("RPG_EFFECT");};var effect=new PotionEffect(type,Math.clamp(event.getDuration(),1,12000),(int)Math.clamp(c.activeValue(),0,4));if(!p.addPotionEffect(effect))return;effects.computeIfAbsent(p.getUniqueId(),key->new HashMap<>()).put(type,effect);}},owner);}
    private void clearEffects(Player p){var own=effects.remove(p.getUniqueId());if(own!=null)own.forEach((type,effect)->{if(effect.equals(p.getPotionEffect(type)))p.removePotionEffect(type);});}
    @EventHandler public void changed(PlayerChangedWorldEvent e){aura.reconcile(e.getPlayer(),abilityAllowed(e.getPlayer()));if(!abilityAllowed(e.getPlayer()))clearEffects(e.getPlayer());}
    @EventHandler public void loaded(org.bukkit.event.world.WorldLoadEvent e){if(!opened||!e.getWorld().getKey().getNamespace().equals("hearth_housing"))return;objects.apply(snapshot.objects()).thenComposeAsync(v->project(),owner).thenComposeAsync(v->applyPvp(),owner).whenCompleteAsync((v,error)->{if(error!=null)hold(error);},owner);}
    @EventHandler public void quit(PlayerQuitEvent e){clearEffects(e.getPlayer());}
    public CompletionStage<Void> drain(){if(changing)return CompletableFuture.failedFuture(new IllegalStateException("RPG_BUSY"));return (platform==null?CompletableFuture.<Void>completedFuture(null):platform.drain()).thenComposeAsync(v->enchants==null?CompletableFuture.completedFuture(null):enchants.drain(),owner);}
    public void close(){closed=true;pulse.cancel();if(platform!=null)platform.close();if(enchants!=null)enchants.close();hud.close();menu.close();rewards.close();objects.close();death.close();HandlerList.unregisterAll(this);for(var p:Bukkit.getOnlinePlayers())clearEffects(p);}
}
